#!/usr/bin/env node
// M9-04A：把 web/src/formula-engine（唯一来源）打包为服务端运行期 ESM bundle。
// 运行时机：npm run build:server（tsc 之后）——产物 server/dist/formulas/engine-bundle/index.mjs。
// 引擎源码不复制、不改写；bundle 仅解决 server 构建 rootDir 无法直接编译 web/ 的物理边界。
import { build } from 'esbuild'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..')
const outfile = join(root, 'server', 'dist', 'formulas', 'engine-bundle', 'index.mjs')

await build({
  entryPoints: [join(root, 'web', 'src', 'formula-engine', 'index.ts')],
  outfile,
  bundle: true,
  platform: 'node',
  format: 'esm',
  target: 'node24',
  logLevel: 'warning',
  legalComments: 'none',
  banner: { js: '// GENERATED by scripts/build/formula-engine-bundle.mjs from web/src/formula-engine — do not edit' },
})
console.log('[formula-engine-bundle] built ' + outfile)
